// Five original environment types per game: distinct geometry, landmarks and terrain rules.
const WORLD_KINDS=['meadow','dinosaur','lunar','water','zombie'];
const WORLD_COURSES={
arena:[['Wildwood Outpost','Animal meadow · split hedges and open flanks'],['Dino Bone Basin','Dinosaur valley · broken fossil cover'],['Lunar Relay Base','Moon station · offset relay bunkers'],['Lagoon Bridge Arena','Water channels · cross the centre bridge'],['Zombie Courtyard','Overgrown quarantine town · barricaded streets']],
rally:[['Wildwood Circuit','Land circuit · broad bends and flower verges'],['Dino Ridge Hairpins','Canyon hairpins · boulders and dinosaur landmarks'],['Lunar Dash Speedway','Moon speedway · long straights and chicanes'],['Lagoon Wake Race','Water course · buoys, islands and side currents'],['Zombie Block Run','Town course · sharp street bends and moving roadblocks']],
leap:[['Treetop Paw Trail','Animal meadow · broad stepped branches'],['Dino Egg Escarpment','Dinosaur cliffs · short landings and fossil ledges'],['Lunar Gravity Towers','Moon base · moving lift platforms'],['Tidepool Island Hop','Over-water adventure · islands and floating docks'],['Rooftop Rescue','Zombie town · roof-to-roof jumps and patrols']],
tower:[['Woodland Animal Refuge','Garden refuge · a long double-bend approach'],['Dino Hatchery Gate','Dinosaur hatchery · a winding canyon route'],['Moon Reactor Bastion','Lunar station · central overlapping firing lanes'],['Lagoon Canal Keep','Water fortress · bridge turns and island build pads'],['Zombie Town Barricade','Town defence · a long street route with close corners']],
dodge:[['Animal Meadow Dash','Meadow arena · warning rings and falling hazards'],['Dino Stomp Valley','Dinosaur zone · larger stomp rings'],['Meteor Moonbase','Lunar zone · crossing warning sweeps'],['Tidal Current Gauntlet','Water arena · drifting currents and buoy routes'],['Zombie Street Survival','Town arena · narrow street sweeps and patrol pressure']],
maze:[['Hedge Paw Labyrinth','Classic hedge maze · winding single-path corridors'],['Dino Ruin Chambers','Ruins maze · open chambers joined by passages'],['Lunar Hub Maze','Station maze · a central hall and connecting corridors'],['Canal Bridge Labyrinth','Canal maze · braided loops and water crossings'],['Zombie Street Grid','Town maze · long streets and connected intersections']],
space:[['Pet Planet Patrol','Animal planet · sweeping drone approach lanes'],['Dino Asteroid Belt','Dinosaur planet · close asteroid formations'],['Lunar Satellite Sector','Moon sector · narrow central drone lanes'],['Ocean Moon Orbit','Ocean planet · wide drifting attack formations'],['Haunted Debris Field','Quarantine sector · flanking drone formations']],
memory:[['Wildwood Archive','Animal vault · a classic matching grid'],['Fossil Memory Dig','Dinosaur dig · staggered rows and fossil symbols'],['Lunar Control Room','Moon station · compact control-panel grid'],['Island Memory Deck','Over-water vault · offset island rows'],['Zombie Code House','Overgrown town · a wider grid of spooky symbols']]
};
for(const mode of Object.keys(WORLD_COURSES))COURSE_SETS[mode]=WORLD_COURSES[mode];
const originalCourseMap=courseMap;courseMap=function(mode=courseMode(),id=selectedCourse(mode)){const map=originalCourseMap(mode,id);map.terrain=WORLD_KINDS[map.baseIndex];map.routeWidth=[190,166,180,176,170][map.baseIndex];if(map.terrain==='water')map.path='#32b9e2';return map};
roadCentre=function(g,d){const i=g.map.baseIndex||0;if(i===0)return 500+Math.sin(d*.0011)*115+Math.sin(d*.00043)*45;if(i===1)return 500+Math.sin(d*.0019)*185+Math.sin(d*.00063)*35;if(i===2)return 500+Math.sin(d*.00065)*55+Math.sin(d*.0027)*45;if(i===3)return 500+Math.sin(d*.00115)*150+Math.sin(d*.003)*35;return 500+Math.tanh(Math.sin(d*.0012)*3)*170};
// Original, friendly cartoon landmarks; no copied characters or external assets.
function worldCreature(c,x,y,type,size=1){c.save();c.translate(x,y);c.scale(size,size);if(type==='dinosaur'){ellipse(c,0,0,28,20,'#72cb68');ellipse(c,24,-18,15,18,'#9be76d');c.fillStyle='#72cb68';c.beginPath();c.moveTo(-17,-8);c.lineTo(-55,-19);c.lineTo(-27,13);c.fill();roundRect(c,-15,12,9,17,3,'#457c50');roundRect(c,12,12,9,17,3,'#457c50');ellipse(c,28,-22,3,4,'#173a44');c.fillStyle='#f3ce66';for(let i=0;i<4;i++){c.beginPath();c.moveTo(-22+i*12,-16);c.lineTo(-17+i*12,-30);c.lineTo(-11+i*12,-15);c.fill()}}else if(type==='zombie'){roundRect(c,-19,-27,38,38,10,'#86d6a1','#254f65');roundRect(c,-22,10,44,33,8,'#9c7ed8','#254f65');ellipse(c,-8,-11,5,6,'#fff2d8');ellipse(c,8,-11,5,6,'#fff2d8');ellipse(c,-8,-11,2,3,'#23304b');ellipse(c,8,-11,2,3,'#23304b');c.strokeStyle='#29475e';c.lineWidth=3;c.beginPath();c.moveTo(-7,2);c.lineTo(8,2);c.stroke();roundRect(c,-32,16,13,10,4,'#86d6a1');roundRect(c,19,16,13,10,4,'#86d6a1')}else{ellipse(c,0,0,23,22,'#fff0d3');ellipse(c,-15,-26,8,21,'#fff0d3');ellipse(c,15,-26,8,21,'#fff0d3');ellipse(c,-15,-27,3,13,'#f2abc0');ellipse(c,15,-27,3,13,'#f2abc0');ellipse(c,-8,-4,3,4,'#24374e');ellipse(c,8,-4,3,4,'#24374e');ellipse(c,0,5,4,3,'#e38fa8')}c.restore()}
const environmentBackdrop=miniBackdrop;miniBackdrop=function(c,g,space=false){environmentBackdrop(c,g,space);const kind=g.map.terrain||WORLD_KINDS[g.map.baseIndex||0];if(space){ellipse(c,890,100,67,67,kind==='water'?'#2589c7':kind==='dinosaur'?'#a9905a':'#7175c6');if(kind==='dinosaur'||kind==='zombie')worldCreature(c,890,103,kind,.8);return}if(kind==='water'){for(let i=0;i<9;i++){const x=60+(i*137)%900,y=90+(i*83)%480;ellipse(c,x,y,43,19,'#1478bd55');c.strokeStyle='#b3f8ff77';c.lineWidth=3;c.beginPath();c.moveTo(x-25,y+Math.sin(g.elapsed+i)*4);c.lineTo(x+25,y+Math.sin(g.elapsed+i)*4);c.stroke()}for(const[x,y]of [[60,135],[940,500]]){ellipse(c,x,y,56,28,'#ffe4a0');ellipse(c,x,y-5,42,18,'#42b675');worldCreature(c,x,y-26,'meadow',.55)}}else if(kind==='dinosaur'){for(const[x,y]of [[60,130],[935,490]]){c.fillStyle='#704c68';c.beginPath();c.moveTo(x-65,y+80);c.lineTo(x,y-30);c.lineTo(x+65,y+80);c.fill();worldCreature(c,x,y+47,'dinosaur',.75)}}else if(kind==='zombie'){for(let i=0;i<5;i++){const x=i%2?950:25,y=70+i*110;roundRect(c,x-35,y-35,70,80,8,'#393b66','#a592c3');roundRect(c,x-22,y-20,14,20,3,'#ffe788');roundRect(c,x+8,y-20,14,20,3,'#ffe788')}worldCreature(c,65,540,'zombie',.8);worldCreature(c,935,130,'zombie',.8)}else if(kind==='lunar'){for(const[x,y]of [[65,160],[935,490]]){ellipse(c,x,y+16,40,16,'#172e6677');roundRect(c,x-22,y-25,44,45,7,'#c9d8ff','#284175');c.strokeStyle='#fff17c';c.lineWidth=4;c.beginPath();c.moveTo(x,y-25);c.lineTo(x,y-58);c.stroke();ellipse(c,x,y-61,7,7,'#64ffe4')}}else{worldCreature(c,50,130,'meadow',.7);worldCreature(c,950,515,'meadow',.7)}};
const environmentRallyUpdate=updateRally;updateRally=function(g,dt,input){if(g.map.terrain==='water')g.x+=Math.sin(g.alt.clock*1.4)*26*dt;for(const o of g.alt.objects)if(g.map.terrain==='zombie'&&!o.hit&&o.kind!=='crystal'){o.baseLane??=o.lane;o.lane=o.baseLane+Math.sin(g.alt.clock*2+o.d)*38}return environmentRallyUpdate(g,dt,input)};
const environmentRallyDraw=drawRally;drawRally=function(c,g){environmentRallyDraw(c,g);const a=g.alt;if(g.map.terrain==='water'){for(const x of [g.x-43,g.x+43])roundRect(c,x-8,g.y-40,16,85,9,'#f5d790','#173f65');for(const o of a.objects)if(o.kind!=='crystal'){ellipse(c,o.x,o.y+5,19,8,'#136eae');roundRect(c,o.x-9,o.y-20,18,28,5,'#ff5c69','#ffe7bd')}}if(g.map.terrain==='dinosaur')for(const o of a.objects)if(o.kind!=='crystal')ellipse(c,o.x,o.y,23,19,'#705963');if(g.map.terrain==='zombie')for(const o of a.objects)if(o.kind!=='crystal')roundRect(c,o.x-27,o.y-12,54,23,5,'#ffa65b','#313456')};
function openMazeEdge(a,index,dir){const x=index%a.cols,y=Math.floor(index/a.cols),dx=[0,1,0,-1][dir],dy=[-1,0,1,0][dir],nx=x+dx,ny=y+dy;if(nx<0||nx>=a.cols||ny<0||ny>=a.rows)return;a.cells[index].walls[dir]=false;a.cells[ny*a.cols+nx].walls[(dir+2)%4]=false}
function rebuildMazeWalls(g){const a=g.alt;a.mazeWalls=[];a.cells.forEach((cell,i)=>{const x=a.ox+(i%a.cols)*a.cell,y=a.oy+Math.floor(i/a.cols)*a.cell;if(cell.walls[0])a.mazeWalls.push({x,y,w:a.cell,h:6});if(cell.walls[3])a.mazeWalls.push({x,y,w:6,h:a.cell});if(i%a.cols===a.cols-1&&cell.walls[1])a.mazeWalls.push({x:x+a.cell,y,w:6,h:a.cell});if(Math.floor(i/a.cols)===a.rows-1&&cell.walls[2])a.mazeWalls.push({x,y:y+a.cell,w:a.cell,h:6})});g.walls=a.mazeWalls}
const environmentMaze=makeRelicMaze;makeRelicMaze=function(g){environmentMaze(g);const a=g.alt,kind=g.map.terrain;const room=(sx,sy,w,h)=>{for(let y=sy;y<Math.min(a.rows-1,sy+h);y++)for(let x=sx;x<Math.min(a.cols-1,sx+w);x++){const i=y*a.cols+x;if(x<sx+w-1)openMazeEdge(a,i,1);if(y<sy+h-1)openMazeEdge(a,i,2)}};
 if(kind==='dinosaur'){room(2,2,3,2);room(a.cols-5,a.rows-4,3,2);room(Math.floor(a.cols/2),2,2,2)}
 if(kind==='lunar'){room(Math.floor(a.cols/2)-2,Math.floor(a.rows/2)-1,5,3);for(let x=1;x<a.cols-2;x++)openMazeEdge(a,Math.floor(a.rows/2)*a.cols+x,1)}
 if(kind==='water')a.cells.forEach((_,i)=>{if(i%3===0&&miniRandom(a)<.7)openMazeEdge(a,i,i%2?1:2)});
 if(kind==='zombie'){for(let y=1;y<a.rows-1;y++)for(const x of [3,a.cols-4])openMazeEdge(a,y*a.cols+x,2);for(let x=1;x<a.cols-1;x++)for(const y of [2,a.rows-3])openMazeEdge(a,y*a.cols+x,1);room(4,3,3,3)}rebuildMazeWalls(g)
};
const environmentMazeDraw=drawMaze;drawMaze=function(c,g){environmentMazeDraw(c,g);const a=g.alt,kind=g.map.terrain,p=mazePoint(a,a.wardenIndex??a.exit);if(kind==='dinosaur'||kind==='zombie')worldCreature(c,p.x,p.y,kind,Math.min(.7,a.cell/80));if(kind==='water'){c.fillStyle='#bbf4ff';c.font='bold 14px sans-serif';c.textAlign='center';c.fillText('CANAL LOOPS · FIND THREE RELICS',500,35)}};
const environmentDodge=updateDodge;updateDodge=function(g,dt,input){if(g.map.terrain==='water'){g.x=Math.max(45,Math.min(955,g.x+Math.sin(g.alt.clock)*30*dt));g.y=Math.max(80,Math.min(600,g.y+12*dt))}if(g.map.terrain==='dinosaur')for(const o of g.alt.objects)if(o.kind==='warning')o.r=Math.max(o.r,57+(g.mission?.threat||1)*2);return environmentDodge(g,dt,input)};
const environmentSpace=updateSpace;updateSpace=function(g,dt,input){const a=g.alt,before=new Set(a.objects);environmentSpace(g,dt,input);for(const e of a.objects)if(!before.has(e)&&!e.guardian){const i=g.map.baseIndex||0;e.x=i===2?350+miniRandom(a)*300:i===4?(miniRandom(a)<.5?100:900):70+miniRandom(a)*860;e.phase+=(i*.7);if(i===1){e.hp*=1.15;e.maxHp=e.hp}if(i===3)e.speed*=.9}};
const environmentMemoryRect=memoryRect;memoryRect=function(g,i){const r=environmentMemoryRect(g,i),kind=g.map.terrain,row=Math.floor(i/g.alt.cols);if(kind==='dinosaur')r.x+=(row%2?16:-16);if(kind==='water'){r.x+=row%2?20:-20;r.y+=Math.sin(i)*5}if(kind==='lunar'){r.w-=6;r.x+=3}return r};
const WORLD_SYMBOLS={meadow:['🐾','🐶','🐱','🐰','🐼','🦊','🐸','🐢','🐙','🐠','🦋','🐝','🦉','🐧','🐥','🦄'],dinosaur:['🦖','🦕','🦴','🥚','🐊','🌋','🪨','🌿','🍃','🦎','🐢','☀','🌴','💎','🦋','🐾'],lunar:['🚀','🛸','🛰','🌙','⭐','☄','🌍','🔭','🧑‍🚀','🪐','🌌','💎','⚡','☀','🔋','📡'],water:['🐠','🐟','🐡','🐙','🦑','🦀','🐚','🪸','🐬','🐳','🐢','🦈','⛵','⚓','🏝','🫧'],zombie:['👻','🧟','🎃','🦇','🕷','🕸','🕯','🧪','⭐','🌙','🗝','🏚','💎','🔮','🦉','🍬']};
const environmentMemoryDraw=drawMemory;drawMemory=function(c,g){const previous=[...VAULT_SYMBOLS];try{VAULT_SYMBOLS.splice(0,VAULT_SYMBOLS.length,...(WORLD_SYMBOLS[g.map.terrain]||previous));environmentMemoryDraw(c,g)}finally{VAULT_SYMBOLS.splice(0,VAULT_SYMBOLS.length,...previous)}};
const environmentBot=drawBot;drawBot=function(c,e,g){if(!['dinosaur','zombie'].includes(g.map.terrain)||e.type==='boss')return environmentBot(c,e,g);c.save();if(e.spawnShield>0)c.globalAlpha=.5;worldCreature(c,e.x,e.y,g.map.terrain,e.type==='tank'?1:.8);roundRect(c,e.x-25,e.y-48,50,5,2,'#1a2e4d');roundRect(c,e.x-25,e.y-48,50*Math.max(0,e.hp/e.maxHp),5,2,'#fff075');c.restore()};
const environmentArenaLayout=arenaLayout;arenaLayout=function(g){const walls=environmentArenaLayout(g);if(g.map.terrain==='water')walls.push({x:g.w*.46,y:64,w:g.w*.08,h:g.h*.25,water:true},{x:g.w*.46,y:g.h*.65,w:g.w*.08,h:g.h*.25,water:true});return walls};
const environmentPaintField=paintField;paintField=function(g){const canvas=environmentPaintField(g),c=canvas.getContext('2d');c.save();c.scale(g.w/1000,g.h/650);worldCreature(c,67,127,g.map.terrain==='dinosaur'?'dinosaur':g.map.terrain==='zombie'?'zombie':'meadow',.65);c.restore();for(const r of g.walls.filter(r=>r.water)){roundRect(c,r.x-3,r.y-3,r.w+6,r.h+6,10,'#bde8ce');roundRect(c,r.x,r.y,r.w,r.h,8,'#148ac8');for(let y=r.y+15;y<r.y+r.h;y+=24){c.strokeStyle='#7ee3ed';c.lineWidth=3;c.beginPath();c.moveTo(r.x+10,y);c.lineTo(r.x+r.w-10,y);c.stroke()}}return canvas};
if(!game&&!window.location.hash.startsWith('#room=')&&!window.location.hash.startsWith('#challenge='))navigate('home');
